#![allow(clippy::excessive_precision)]

use thermopack_rs::{Cubic, CubicKind, CubicOptions, MixingRule};

#[test]
fn test_srk_c1_h2o_hv1() {
    let options = CubicOptions {
        mixing_rule: MixingRule::HuronVidal1,
        ..Default::default()
    };
    let eos = Cubic::with_options(CubicKind::SoaveRedlichKwong, &["C1", "H2O"], options).unwrap();
    assert_eq!(eos.mixing_rule, MixingRule::HuronVidal1);

    // Point: T = 300.0 K, V = 0.001 m^3/mol, z = [0.5, 0.5]
    let prep = eos.prepare(300.00, &[0.5, 0.5]).unwrap();
    let p_res = prep.pressure(1.000000e-03).unwrap();
    assert!(
        (p_res.value - 2.0442331067927286e+06).abs() < 2.0442331067927287e+02,
        "P diff: {}",
        (p_res.value - 2.0442331067927286e+06).abs()
    );
    let mut lnphi = vec![0.0; 2];
    prep.ln_fugacity_into(1.000000e-03, &mut lnphi).unwrap();
    assert!(
        (lnphi[0] - 2.6485205978527104e-02).abs() < 1e-4,
        "lnphi[0] diff: {}",
        (lnphi[0] - 2.6485205978527104e-02).abs()
    );
    assert!(
        (lnphi[1] - -3.5618407386522538e-01).abs() < 1e-4,
        "lnphi[1] diff: {}",
        (lnphi[1] - -3.5618407386522538e-01).abs()
    );

    // Point: T = 350.0 K, V = 0.0005 m^3/mol, z = [0.8, 0.2]
    let prep = eos.prepare(350.00, &[0.8, 0.2]).unwrap();
    let p_res = prep.pressure(5.000000e-04).unwrap();
    assert!(
        (p_res.value - 5.3088028692811951e+06).abs() < 5.3088028692811952e+02,
        "P diff: {}",
        (p_res.value - 5.3088028692811951e+06).abs()
    );
    let mut lnphi = vec![0.0; 2];
    prep.ln_fugacity_into(5.000000e-04, &mut lnphi).unwrap();
    assert!(
        (lnphi[0] - -8.8570412546951777e-03).abs() < 1e-4,
        "lnphi[0] diff: {}",
        (lnphi[0] - -8.8570412546951777e-03).abs()
    );
    assert!(
        (lnphi[1] - -4.1221004046454834e-01).abs() < 1e-4,
        "lnphi[1] diff: {}",
        (lnphi[1] - -4.1221004046454834e-01).abs()
    );

    // Point: T = 400.0 K, V = 0.0001 m^3/mol, z = [0.2, 0.8]
    let prep = eos.prepare(400.00, &[0.2, 0.8]).unwrap();
    let p_res = prep.pressure(1.000000e-04).unwrap();
    assert!(
        (p_res.value - -9.5472983219982199e+06).abs() < 9.5472983219982200e+02,
        "P diff: {}",
        (p_res.value - -9.5472983219982199e+06).abs()
    );
}

